package ama.task;
import ama.contract.TaskContracts.*;import ama.contract.ExternalContracts.*;
import org.junit.jupiter.api.*;import java.util.*;import java.time.*;import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
class ModelPermitIT {
 TaskFixture f;JdbcTaskQueue q;JdbcExternalOperations e;String model;
 @BeforeEach void setup(){f=new TaskFixture();q=f.queue();e=new JdbcExternalOperations(q);model="TEST_"+UUID.randomUUID();}
 OperationToken token(){var s=f.spec();var l=f.claimed(q,s);return e.beginExternal(l,new ExternalRequest("TEST_CALL",s.producerKey(),TaskFixture.hash(s.producerKey()),TaskFixture.hash(s.input().id()),"test-v1:"+s.input().id())).orElseThrow();}
 JdbcModelPermitPool pool(int capacity,long revision,boolean enabled,ModelConfiguration.CutoffPolicy cutoff){return new JdbcModelPermitPool(e,Map.of(model,new ModelConfiguration(model,capacity,revision,enabled,cutoff)),(t,m,d)->{if(!m.startsWith("TEST_"))throw new IllegalArgumentException();});}
 @Test void concurrentAdmissionRetainsNullDeadlineAfterTimeout()throws Exception{var p=pool(1,1,true,ModelConfiguration.CutoffPolicy.EXPLICIT_SETTLEMENT);p.configure();var a=token();var b=token();var go=new CountDownLatch(1);try(var threads=Executors.newFixedThreadPool(2)){var x=threads.submit(()->{go.await();return p.acquire(a,model,null);});var y=threads.submit(()->{go.await();return p.acquire(b,model,null);});go.countDown();var one=x.get(5,TimeUnit.SECONDS);var two=y.get(5,TimeUnit.SECONDS);assertEquals(1,(one.isPresent()?1:0)+(two.isPresent()?1:0));var permit=one.orElseGet(two::orElseThrow);f.j.update("UPDATE external_operation SET reconcile_expires_at=UTC_TIMESTAMP(6)-INTERVAL 1 SECOND WHERE id=?",one.isPresent()?a.operationId():b.operationId());assertFalse(p.settled(permit));assertEquals(1,f.j.queryForObject("SELECT COUNT(*) FROM model_reservation WHERE model=? AND safe_deadline IS NULL AND settled_at IS NULL",Integer.class,model));}}
 @Test void unknownDisabledAndUnprovenDeadlineFailClosed(){var p=pool(1,1,true,ModelConfiguration.CutoffPolicy.EXPLICIT_SETTLEMENT);p.configure();var t=token();assertTrue(new JdbcModelPermitPool(e,Map.of(),(a,b,c)->{}).acquire(t,model,null).isEmpty());assertThrows(IllegalArgumentException.class,()->p.acquire(t,model,Instant.now().plusSeconds(60)));var disabled=pool(1,2,false,ModelConfiguration.CutoffPolicy.EXPLICIT_SETTLEMENT);disabled.configure();assertTrue(p.acquire(t,model,null).isEmpty());assertTrue(disabled.acquire(t,model,null).isEmpty());}
 @Test void shrinkCannotUndercutInflightAndExactTerminalExecutionSettles(){var p=pool(2,1,true,ModelConfiguration.CutoffPolicy.EXPLICIT_SETTLEMENT);p.configure();var a=token();var b=token();var pa=p.acquire(a,model,null);var pb=p.acquire(b,model,null);assertTrue(pa.isPresent());assertTrue(pb.isPresent());assertThrows(IllegalStateException.class,()->pool(1,2,true,ModelConfiguration.CutoffPolicy.EXPLICIT_SETTLEMENT).configure());assertFalse(p.settled(pa.orElseThrow()));var task=f.j.queryForObject("SELECT task_id FROM external_execution WHERE id=?",String.class,a.executionId());var s=q.row(task,false,false).orElseThrow().spec();assertEquals(ObservationResult.APPLIED,e.observe(a,new ExternalObservation(ExternalOutcome.SUCCEEDED,"TEST_RESULT:"+s.input().id(),s.input(),null,null),()->{}));assertTrue(p.settled(pa.orElseThrow()));assertTrue(p.settled(pa.orElseThrow()));assertFalse(p.settled(pb.orElseThrow()));}
 @Test void verifiedCutoffReleasesOnlyAfterActualDbDeadline()throws Exception{var p=pool(1,1,true,ModelConfiguration.CutoffPolicy.PROVEN_DEADLINE);p.configure();var a=token();var b=token();var first=p.acquire(a,model,Instant.now().plusSeconds(2));assertTrue(first.isPresent());assertTrue(p.acquire(b,model,Instant.now().plusSeconds(60)).isEmpty());Thread.sleep(2200);assertTrue(p.acquire(b,model,Instant.now().plusSeconds(60)).isPresent());assertTrue(p.settled(first.orElseThrow()));}
 @Test void concurrentConfigurationUsesStableModelOrder()throws Exception{String other="TEST_"+UUID.randomUUID();var a=new ModelConfiguration(model,1,1,true,ModelConfiguration.CutoffPolicy.EXPLICIT_SETTLEMENT);var b=new ModelConfiguration(other,1,1,true,ModelConfiguration.CutoffPolicy.EXPLICIT_SETTLEMENT);var left=new LinkedHashMap<String,ModelConfiguration>();left.put(model,a);left.put(other,b);var right=new LinkedHashMap<String,ModelConfiguration>();right.put(other,b);right.put(model,a);var first=new JdbcModelPermitPool(e,left,(x,y,z)->{});var second=new JdbcModelPermitPool(e,right,(x,y,z)->{});var start=new CountDownLatch(1);try(var threads=Executors.newFixedThreadPool(2)){var x=threads.submit(()->{start.await();first.configure();return true;});var y=threads.submit(()->{start.await();second.configure();return true;});start.countDown();assertTrue(assertDoesNotThrow(()->x.get(10,TimeUnit.SECONDS)));assertTrue(assertDoesNotThrow(()->y.get(10,TimeUnit.SECONDS)));}assertEquals(2,f.j.queryForObject("SELECT COUNT(*) FROM model_capacity WHERE model IN (?,?)",Integer.class,model,other));}
 @Test void provenDeadlineTruncatesMicrosAndNeverReleasesEarly(){var p=pool(1,1,true,ModelConfiguration.CutoffPolicy.PROVEN_DEADLINE);p.configure();var t=token();Instant deadline=Instant.now().plusSeconds(30).with(java.time.temporal.ChronoField.NANO_OF_SECOND,123456789);var permit=p.acquire(t,model,deadline);assertTrue(permit.isPresent());assertEquals(123456000,permit.orElseThrow().safeDeadline().getNano());assertFalse(p.settled(permit.orElseThrow()));assertThrows(IllegalStateException.class,()->f.tx.required(()->p.acquire(t,model,deadline)));}
 @Test void copiedAndReconciliationTokensCannotAdmitAndDuplicateCannotResend(){
  var p=pool(2,1,true,ModelConfiguration.CutoffPolicy.EXPLICIT_SETTLEMENT);p.configure();var t=token();
  var copied=new OperationToken(t.operationId(),t.executionId(),t.executionNo(),t.reconcileEpoch(),t.owner(),t.expiresAt(),t.subject());
  assertTrue(p.acquire(copied,model,null).isEmpty());assertTrue(p.acquire(t,model,null).isPresent());assertTrue(p.acquire(t,model,null).isEmpty());
  f.j.update("UPDATE external_operation SET next_check_at=UTC_TIMESTAMP(6)-INTERVAL 1 SECOND,reconcile_expires_at=UTC_TIMESTAMP(6)-INTERVAL 1 SECOND WHERE id=?",t.operationId());
  var claimed=e.claimReconciliation("permit-reconciler");for(int i=0;i<200&&claimed.isPresent()&&!claimed.orElseThrow().operationId().equals(t.operationId());i++)claimed=e.claimReconciliation("permit-reconciler");
  assertTrue(claimed.isPresent());assertEquals(t.operationId(),claimed.orElseThrow().operationId());assertTrue(p.acquire(claimed.orElseThrow(),model,null).isEmpty());
 }

}
